<script setup>
import {ref,reactive,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {projectWaterAccounting} from '../../domain/water-accounting.js'
import DataTable from '../../components/DataTable.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import Pagination from '../../components/Pagination.vue'
import BaseModal from '../../components/BaseModal.vue'
import {columns,fmt,methods,clone,requestKey} from '../strategies/operationUi.js'
const r=useIrrigation(),route=useRoute(),router=useRouter(),run=computed(()=>(r.state.entities.IrrigationRun??[]).find(x=>x.runId===route.params.id)),tab=ref(route.query.tab||((route.params.id==='RUN-JZ-18E71500')?'WATER':'STEPS')),pages=reactive({STEPS:1,COMMANDS:1,WATER:1}),page=computed({get:()=>pages[tab.value]||1,set:v=>pages[tab.value]=v}),modal=ref(false),action=ref(''),selected=ref(null),reason=ref(''),failure=ref(''),busy=ref(false),key=requestKey()
const selectedCommand=ref(null)
const water=computed(()=>{try{return {...projectWaterAccounting(r.getIndex()),error:null}}catch(e){return {rows:[],byRun:[],error:e.message}}}),ledger=computed(()=>water.value.rows.filter(x=>x.runId===run.value?.runId)),settled=computed(()=>water.value.byRun.find(x=>x.runId===run.value?.runId)?.volumeM3??0),steps=computed(()=>(r.state.entities.RunStep??[]).filter(x=>x.runId===run.value?.runId).sort((a,b)=>{const pa=r.getIndex().byId.PlanStep.get(a.planStepId),pb=r.getIndex().byId.PlanStep.get(b.planStepId);return (pa?.order??0)-(pb?.order??0)})),commands=computed(()=>(r.state.entities.CommandOutbox??[]).filter(x=>x.runId===run.value?.runId).sort((a,b)=>Date.parse(a.requestedAt)-Date.parse(b.requestedAt))),last=computed(()=>commands.value.find(x=>x.commandId===selectedCommand.value)||commands.value.find(x=>x.commandId===run.value?.lastCommandId)||commands.value.at(-1)),rows=computed(()=>tab.value==='WATER'?ledger.value:tab.value==='COMMANDS'?commands.value:steps.value),visible=computed(()=>rows.value.slice((page.value-1)*15,page.value*15)),cols=computed(()=>tab.value==='WATER'?columns([['number','#',65],['ledgerId','账本编号',220],['zoneId','分区',220],['startedAt','开始时间',205],['endedAt','结束时间',205],['volumeM3','水量 m³',135],['method','计量',120]]):tab.value==='COMMANDS'?columns([['number','#',60],['commandId','指令编号',225],['intent','动作',110],['status','阶段',135],['devices','目标设备',160],['requestedAt','受理时间',200],['sentAt','发送时间',190],['ackAt','通信应答',200],['confirmedAt','动作确认',200],['reason','原因',230]]):columns([['number','顺序',60],['runStepId','步骤编号',200],['zoneId','分区',205],['targetVolumeM3','目标 m³',105],['startedAt','开始时间',190],['endedAt','结束时间',190],['status','状态',115],['endReason','结束原因',150]]))
const labels={RUN_PAUSE:'暂停',RUN_RESUME:'恢复',RUN_STOP:'停止'}
function eligible(a){const statuses={RUN_PAUSE:['RUNNING'],RUN_RESUME:['PAUSED'],RUN_STOP:['RUNNING','STARTING','PAUSED','PAUSING','RESUMING','UNKNOWN','ADVANCING']};return !!run.value&&statuses[a].includes(run.value.status)&&r.can(a,run.value)}
function back(){router.push(route.query.from?.startsWith('/')?route.query.from:'/runs')}
function control(a){action.value=a;selected.value=clone(run.value);reason.value='';failure.value='';modal.value=true}
async function submit(){busy.value=true;failure.value='';try{if(reason.value.trim().length<6)throw new Error('操作原因至少6字');const payload={runId:selected.value.runId,reason:reason.value};await r.commit(action.value,payload,{expectedVersion:selected.value.version,clientRequestId:key(payload)});modal.value=false}catch(e){failure.value=e.message}finally{busy.value=false}}
function stageTime(field,phase){const command=last.value;if(!command)return null;return command[field]||(r.state.entities.CommandEvent??[]).find(e=>e.commandId===command.commandId&&e.phase===phase)?.occurredAt}
</script>
<template><div v-if="run" class="page-stack run-detail"><div class="run-heading"><button class="btn" @click="back">〈　返回</button><strong>运行编号: {{run.runId}}</strong><span class="run-meta">关联计划: <button class="btn-link" @click="router.push({path:'/plans/'+run.planId+'/edit',query:{from:route.fullPath}})">{{run.planId}}</button>　|　版本: {{run.version}}　|　状态: <StatusBadge :status="run.status"/></span><div class="controls"><button v-for="(label,a) in labels" :key="a" class="btn" :disabled="!eligible(a)" :title="eligible(a)?label+'运行':'当前状态或权限不允许'+label" @click="control(a)">{{({RUN_PAUSE:'Ⅱ',RUN_RESUME:'▶',RUN_STOP:'■'})[a]}}　{{label}}</button></div></div><div class="run-summary"><section class="panel"><span class="summary-icon green">▣</span><div><span>开始时间</span><strong>{{fmt(run.actualStartedAt)}}</strong></div></section><section class="panel"><span class="summary-icon red">▣</span><div><span>结束时间</span><strong>{{fmt(run.actualEndedAt)}}</strong></div></section><section class="panel"><span class="summary-icon blue">♧</span><div><span>已结算水量</span><strong>{{settled.toFixed(1)}} m³</strong></div></section></div><section class="panel detail-table"><div class="tabs"><button v-for="(name,id) in {STEPS:'轮灌步骤',COMMANDS:'指令记录',WATER:'计量明细'}" :key="id" class="tab" :class="{active:tab===id}" @click="tab=id">{{name}}</button></div><p v-if="water.error" role="alert" class="error-text">{{water.error}}</p><div class="table-content"><DataTable :columns="cols" :rows="visible" :row-key="tab==='WATER'?'ledgerId':tab==='COMMANDS'?'commandId':'runStepId'" @row-click="selected=$event;if(tab==='COMMANDS')selectedCommand=$event.commandId"><template #cell-number="{index}">{{(page-1)*15+index+1}}</template><template #cell-zoneId="{value}">{{r.getIndex().byId.IrrigationZone.get(value)?.name||value}}</template><template #cell-startedAt="{value}">{{fmt(value,true)}}</template><template #cell-endedAt="{value}">{{fmt(value,true)}}</template><template #cell-requestedAt="{value}">{{fmt(value,true)}}</template><template #cell-ackAt="{value}">{{fmt(value,true)}}</template><template #cell-confirmedAt="{value}">{{fmt(value,true)}}</template><template #cell-volumeM3="{value}">{{Number(value).toFixed(1)}}</template><template #cell-method="{value}">{{methods[value]||value}}</template><template #cell-status="{value}"><StatusBadge :status="value"/></template><template #cell-devices="{row}">{{[...new Set((r.state.entities.CommandEvent??[]).filter(e=>e.commandId===row.commandId).map(e=>e.deviceId).filter(Boolean))].join('、')||'—'}}</template><template #cell-sentAt="{row}">{{fmt(row.sentAt||(r.state.entities.CommandEvent??[]).find(e=>e.commandId===row.commandId&amp;&amp;e.phase==='SENT')?.occurredAt,true)}}</template><template #cell-intent="{value}">{{({START:'启动',PAUSE:'暂停',RESUME:'恢复',STOP:'停止'})[value]||value}}</template></DataTable><Pagination v-if="rows.length>15" v-model="page" :total="rows.length"/></div></section><section class="panel command-timeline"><h2 class="panel-title">末次指令：{{last?.commandId||'暂无指令'}}</h2><div v-if="last" class="stages"><div v-for="(stage,i) in [{title:'已受理',at:stageTime('requestedAt','ACCEPTED')},{title:'通信应答',at:stageTime('ackAt','ACKNOWLEDGED')},{title:'动作确认',at:stageTime('confirmedAt','ACTION_CONFIRMED')}]" :key="i" :class="{done:!!stage.at}"><span class="stage-dot">{{stage.at?'✓':'·'}}</span><strong>{{stage.title}}</strong><span>{{stage.at?fmt(stage.at):'待反馈'}}</span></div></div><p v-else class="muted">该运行暂无指令记录</p><p v-if="last?.failureCode" class="error-text">{{last.failureCode}}</p></section><BaseModal v-model="modal" :title="labels[action]+'运行'" :busy="busy"><p>{{selected?.runId}}</p><p>该操作将请求现场泵阀联动，动作确认后更新运行状态。</p><label class="filter-field">操作原因<textarea v-model="reason" rows="3" placeholder="至少6字"/></label><p v-if="failure" role="alert" class="error-text">{{failure}}</p><template #footer><button class="btn" :disabled="busy" @click="modal=false">取消</button><button class="btn btn-primary" :disabled="busy" @click="submit">确认{{labels[action]}}</button></template></BaseModal></div><section v-else class="panel empty-state">{{r.state.ready?'运行不存在或无权访问':'加载中…'}} <button class="btn" @click="back">返回</button></section></template>
<style scoped>.run-detail{gap:16px}.run-heading{display:flex;align-items:center;gap:26px;min-height:48px}.run-heading>strong{font-size:19px;white-space:nowrap}.run-meta{font-size:12px;color:#698089;white-space:nowrap}.run-meta .btn-link{font-size:12px}.controls{display:flex;gap:12px;margin-left:auto}.controls .btn{padding:8px 14px;min-width:92px}.run-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.run-summary .panel{min-height:93px;display:flex;align-items:center;gap:26px;padding:15px 20px}.summary-icon{display:grid;place-items:center;border-radius:50%;width:58px;height:58px;font-size:35px;background:#e9f8f1;color:#13875c}.summary-icon.red{background:#fff2f2;color:#e7405c}.summary-icon.blue{background:#eef5fe;color:#0963ed}.run-summary .panel>div>span{color:#587581;display:block;margin-bottom:8px}.run-summary strong{font-size:22px;white-space:nowrap}.detail-table{padding:0}.detail-table .tabs{padding:0 20px}.detail-table .tab{min-width:150px;font-size:17px}.table-content{padding:14px 21px 6px}.table-content :deep(td){height:32px;padding-top:3px;padding-bottom:3px}.command-timeline{padding:16px 24px 18px}.command-timeline .panel-title{font-size:19px;margin-bottom:8px}.stages{display:flex;margin:0 100px}.stages>div{flex:1;display:flex;align-items:center;flex-direction:column;position:relative;color:#637d85;gap:7px}.stages>div:not(:last-child):after{content:'';position:absolute;top:10px;left:50%;width:100%;height:4px;background:#cbd8d3}.stages>div.done:not(:last-child):after{background:#109860}.stage-dot{border-radius:50%;background:#bccbc4;color:white;width:21px;height:21px;display:grid;place-items:center;z-index:1}.done .stage-dot{background:#109860}.stages strong{color:#19332e;font-weight:500}</style>
